{"file_path":"/work/tests/test_spec.py","content":""""Regression tests for the behavior specified in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("a", 1, None)]) == 0.0


def test_conversion_rate_empty():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 1, False), session("c", 1, None), session("d", 1, True)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_rate_no_sessions(groups):
    result = pooled_conversion_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4, 8], 2, 12), ([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0), ([], 0, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_flags_and_field_whitespace():
    assert parse_session_log([" a , 3 , 1 \n", " b , -2 , 0 ", " c , 4 , \t"]) == [
        session("a", 3, True), session("b", -2, False), session("c", 4, None),
    ]


def test_parse_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "#comment", "  \t# not,a,session,record", "a,1,1"]
    assert parse_session_log(iter(lines)) == [session("a", 1, True)]
    assert parse_session_log(lines[:-1]) == []
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["a", "a,1", "a,1,1,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["", " # comment", "ok,1,1", " \t", bad_line])


def test_parse_hash_inside_id_is_not_a_comment():
    assert parse_session_log(["a#b,1,0"]) == [session("a#b", 1, False)]


def test_dedupe_keeps_last_duplicate_id_and_sorts():
    events = [
        session("b", 9, True), session("a", 2, True), session("c", 1, None),
        session("b", 2, False), session("a", 2, None),
    ]
    original = [dict(event) for event in events]
    assert dedupe_sessions(events) == [events[2], events[4], events[3]]
    assert events == original
    assert dedupe_sessions([]) == []


def test_daily_counts_fill_gaps_and_ignore_outside_range():
    events = [
        session("a", 1, True), session("b", 2, True), session("c", 2, True),
        session("d", 3, None), session("e", 3, False), session("f", 5, True),
        session("g", 6, True),
    ]
    assert daily_conversion_counts(events, 2, 5) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 2, 2) == [2]
    assert daily_conversion_counts(events, 5, 2) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_campaign_summary_uses_calendar_days_pooled_rate_and_nonempty_groups(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 4, True), session("c", 5, False)],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize(
    "n, expected",
    [(0, []), (1, ["best"]), (2, ["best", "a"]), (10, ["best", "a", "z", "zero"])],
)
def test_top_groups_excludes_empty_and_sorts_ties_by_name(n, expected):
    groups = {
        "z": [session("a", 1, True), session("b", 1, None)],
        "zero": [session("a", 1, False)],
        "empty": [],
        "a": [session("a", 1, True), session("b", 1, False)],
        "best": [session("a", 1, True)],
    }
    assert top_converting_groups(groups, n) == expected
    assert top_converting_groups({}, n) == []
    assert top_converting_groups({"empty": []}, n) == []


def test_rate_by_group_sorted_keys_and_empty_is_none():
    groups = {
        "z": [], "c": [session("a", 1, None)],
        "a": [session("a", 1, True), session("b", 1, None)],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": 0.5, "c": 0.0, "z": None}
    assert list(result) == ["a", "c", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5, 0, 1], 3),
     ([1, -1, 1], 1), ([1, 2, 3], 3), ([0, 1, 0], 1)],
)
def test_longest_streak_requires_consecutive_positive_entries(counts, expected):
    assert longest_conversion_streak(counts) == expected
